class SecretDetector : Detector(), SourceCodeScanner, XmlScanner {

    companion object {
        val ISSUE = Issue.create(
            id = "SecretInSource",
            briefDescription = "Secret in source code",
            explanation = """
                Including secrets, such as API keys, in source code is a security risk.
                It is generally best practice to not include API keys in source code,
                and instead use something like the Secrets Gradle Plugin for Android.
            """.trimIndent(),
            moreInfo = "https://developers.google.com/maps/documentation/android-sdk/secrets-gradle-plugin",
            category = Category.SECURITY,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                SecretDetector::class.java,
                EnumSet.of(Scope.JAVA_FILE, Scope.RESOURCE_FILE, Scope.MANIFEST)
            )
        )

        private val SECRET_NAME_REGEX = Regex(
            "(api[_\\s-]?key|secret|token|password|auth|private|credential)",
            RegexOption.IGNORE_CASE
        )
        private val SUSPICIOUS_VALUE_REGEX = Regex(
            "^(?=.*[A-Za-z])(?=.*\\d)[A-Za-z0-9_\\-]{16,}$"
        )
    }

    // Source code scanning
    override fun getApplicableUastTypes(): List<Class<out UElement>>? {
        return listOf(ULiteralExpression::class.java)
    }

    override fun createUastHandler(context: JavaContext): UElementHandler? {
        return object : UElementHandler() {
            override fun visitLiteralExpression(node: ULiteralExpression) {
                val value = node.value as? String ?: return
                // maybe skip URLs
                if (value.length < 8) return
                val parent = node.uastParent ?: return
                // Check variable or field name containing secret terms, or value looks like key
                if (isSecretName(parent) || SUSPICIOUS_VALUE_REGEX.matches(value)) {
                    // avoid reporting empty/template strings
                    if (value.contains("\${") || value.contains("BuildConfig")) return
                    context.report(ISSUE, node, context.getLocation(node), "Possible secret in source code")
                }
            }
        }
    }

    private fun isSecretName(element: UElement?): Boolean {
        // Need inspect parent for variable/field name
        // If parent is UVariable? In UAST, ULiteralExpression is child of UVariable's initializer, not the variable itself. We can check containing variable.
        val variable = (element as? UVariable) ?: (element?.uastParent as? UVariable) ?: return false
        val name = variable.name ?: return false
        return SECRET_NAME_REGEX.containsMatchIn(name)
    }

    // XML scanning
    override fun getApplicableElements(): Collection<String>? {
        return XmlScannerConstants.ALL
    }

    override fun visitElement(context: XmlContext, element: org.w3c.dom.Element) {
        // Check attributes
        for (i in 0 until element.attributes.length) {
            val attr = element.attributes.item(i) as? org.w3c.dom.Attr ?: continue
            val attrName = attr.name
            val attrValue = attr.value ?: continue
            if (attrValue.startsWith("@") || attrValue.startsWith("\$")) continue
