            if (SECRET_NAME_REGEX.containsMatchIn(attrName) || SUSPICIOUS_VALUE_REGEX.matches(attrValue)) {
                context.report(ISSUE, attr, context.getLocation(attr), "Possible secret in XML")
            }
        }
        // Check text content? For strings.xml string elements, value in text node.
        val text = element.textContent?.trim() ?: ""
        if (text.length >= 8 && !text.startsWith("@")) {
            val tagName = element.tagName ?: ""
